  getr r8 22 = Z_to_bv 64 1483096 -> getr r8 24 = Z_to_bv 64 0 -> getr r8 25 = Z_to_bv 64 (ab + rz + n) ->
  (* [comment removed for export] *)
  4096 <= n < 2 ^ 39 -> n = 8 * qn + m8 -> 0 <= m8 <= 7 -> rs = 8 * qr -> n <= rs <= n + 7 -> rz = 16 * qz -> 32 <= rz <= 2048 ->
  nd = rs + rz + rz -> 65536 < nd -> 4096 * (q - 1) < nd <= 4096 * q ->
  (* [comment removed for export] *)
  0x10007fff8000 + 4096 <= sp -> sp + 2144 <= 2 ^ 47 ->
  4096 <= t -> t + 4096 < 2 ^ 47 -> (t + 4096 <= 0x10000 \/ 0x6c4000 <= t) -> apart t 4096 (sp - 1952) 6048 -> apart t 4096 0x7fff8000 0x100000000000 ->
  apart ctx 4096 (sp - 1952) 6048 -> (ctx + 4096 <= 0x10000 \/ 0x6c4000 <= ctx) -> apart t 4096 ctx 4096 -> apart ctx 4096 0x7fff8000 0x100000000000 ->
  0 <= loff -> 0x10100 <= tp -> tp + 8 <= 0x6c4000 -> 0x10000 <= tp + loff -> tp + loff + 4 <= 0x6c4000 -> 0x10000 <= tsd -> tsd + 1024 <= 0x6c4000 ->
  ab mod 4096 = 0 -> 0x6c4000 + 4096 <= ab -> (ab + 4096 * q < 0x7fff8000 \/ 0x10007fff8000 + 4096 <= ab) -> ab + 4096 * q < 2 ^ 47 ->
  apart (ab - 4096) (4096 * q + 4096) (sp - 1952) 6048 -> apart (ab - 4096) (4096 * q + 4096) t 4096 -> apart (ab - 4096) (4096 * q + 4096) ctx 4096 ->
